installed_keystone.password_authentication:
def authenticate(self, auth_payload):
    """Try to authenticate against the identity backend."""
    response_data = {}
    user_info = auth_plugins.UserAuthInfo.create(auth_payload, METHOD_NAME)

    try:
        PROVIDERS.identity_api.authenticate(
            user_id=user_info.user_id, password=user_info.password
        )
    except AssertionError:
        # authentication failed because of invalid username or password
        msg = _('Invalid username or password')
        raise exception.Unauthorized(msg)

    response_data['user_id'] = user_info.user_id

    return base.AuthHandlerResponse(
        status=True, response_body=None, response_data=response_data
    )

installed_keystone.trust_roles:
def _get_trust_roles(self):
    roles = []
    # If redelegated_trust_id is set, then we must traverse the trust_chain
    # in order to determine who the original trustor is. We need to do this
    # because the user ID of the original trustor helps us determine scope
    # in the redelegated context.
    if self.trust.get('redelegated_trust_id'):
        trust_chain = PROVIDERS.trust_api.get_trust_pedigree(self.trust_id)
        original_trustor_id = trust_chain[-1]['trustor_user_id']
    else:
        original_trustor_id = self.trustor['id']

    trust_roles = [{'role_id': role['id']} for role in self.trust['roles']]
    effective_trust_roles = PROVIDERS.assignment_api.add_implied_roles(
        trust_roles
    )
    effective_trust_role_ids = {
        r['role_id'] for r in effective_trust_roles
    }

    current_effective_trustor_roles = (
        PROVIDERS.assignment_api.get_roles_for_trustor_and_project(
            original_trustor_id, self.trust.get('project_id')
        )
    )

    for trust_role_id in effective_trust_role_ids:
        if trust_role_id in current_effective_trustor_roles:
            role = PROVIDERS.role_api.get_role(trust_role_id)
            if role['domain_id'] is None:
                roles.append(role)
        else:
            raise exception.Forbidden(_('Trustee has no delegated roles.'))

    return roles

installed_additional_authentication_sour.default_scope:
def _check_and_set_default_scoping(auth_info, auth_context):
    (domain_id, project_id, trust, unscoped, system) = auth_info.get_scope()
    if trust:
        project_id = trust['project_id']
    if system or domain_id or project_id or trust:
        # scope is specified
        return

    # Skip scoping when unscoped federated token is being issued
    if constants.IDENTITY_PROVIDER in auth_context:
        return

    # Do not scope if request is for explicitly unscoped token
    if unscoped is not None:
        return

    # fill in default_project_id if it is available
    try:
        user_ref = PROVIDERS.identity_api.get_user(auth_context['user_id'])
    except exception.UserNotFound as e:
        LOG.warning(e)
        raise exception.Unauthorized(e)

    default_project_id = user_ref.get('default_project_id')
    if not default_project_id:
        # User has no default project. They shall get an unscoped token.
        msg = (
            "User %(user_id)s doesn't have a default project. "
            " The token will be unscoped rather than scoped to a project."
        )
        LOG.debug(msg, {'user_id': user_ref['id']})
        return

    # make sure user's default project is legit before scoping to it
    try:
        default_project_ref = PROVIDERS.resource_api.get_project(
            default_project_id
        )
        default_project_domain_ref = PROVIDERS.resource_api.get_domain(
            default_project_ref['domain_id']
        )
        if default_project_ref.get(
            'enabled', True
        ) and default_project_domain_ref.get('enabled', True):
            if PROVIDERS.assignment_api.get_roles_for_user_and_project(
                user_ref['id'], default_project_id
            ):
                auth_info.set_scope(project_id=default_project_id)
            else:
                msg = (
                    "User %(user_id)s doesn't have access to"
                    " default project %(project_id)s. The token"
                    " will be unscoped rather than scoped to the"
                    " project."
                )
                LOG.debug(
                    msg,
                    {
                        'user_id': user_ref['id'],
                        'project_id': default_project_id,
                    },
                )
        else:
            msg = (
                "User %(user_id)s's default project %(project_id)s"
                " is disabled. The token will be unscoped rather"
                " than scoped to the project."
            )
            LOG.debug(
                msg,
                {'user_id': user_ref['id'], 'project_id': default_project_id},
            )
    except (exception.ProjectNotFound, exception.DomainNotFound):
        # default project or default project domain doesn't exist,
        # will issue unscoped token instead
        msg = (
            "User %(user_id)s's default project %(project_id)s not"
            " found. The token will be unscoped rather than"
            " scoped to the project."
        )
        LOG.debug(
            msg, {'user_id': user_ref['id'], 'project_id': default_project_id}
        )
